def try_to_cast_to_array_like(
    value: Any
) -> Optional[Sequence[Any]]:
    """
    Try to cast :paramref:`value` to something like a JSON array.

    A mapping and a set are refused, as neither is a JSON array, and so are
    a ``str``, a ``bytes`` and a ``bytearray``, which Python counts among
    the sequences but JSON does not.

    Only a sequence is admitted, and never an arbitrary iterable. A one-shot
    iterable such as a generator is spent by the first walk over it, so
    a verification followed by a serialization would silently give an empty
    array -- this function is the single place where all the modules agree on
    what an array is, so the refusal has to hold for all of them.

    >>> assert try_to_cast_to_array_like(True) is None

    >>> assert try_to_cast_to_array_like(0) is None

    >>> assert try_to_cast_to_array_like(2.2) is None

    >>> assert try_to_cast_to_array_like("hello") is None

    >>> assert try_to_cast_to_array_like(b"hello") is None

    >>> try_to_cast_to_array_like([1, 2])
    [1, 2]

    >>> assert try_to_cast_to_array_like({"a": 3}) is None

    >>> assert try_to_cast_to_array_like(collections.OrderedDict()) is None

    >>> try_to_cast_to_array_like(range(1, 2))
    range(1, 2)

    >>> try_to_cast_to_array_like((1, 2))
    (1, 2)

    >>> assert try_to_cast_to_array_like({1, 2, 3}) is None

    >>> assert try_to_cast_to_array_like(iter([1, 2])) is None
    """
    # NOTE (mristin):
    # A ``list`` is what :py:mod:`json` gives us, and ``isinstance`` against
    # a concrete class costs a fraction of ``isinstance`` against the abstract
    # :py:class:`collections.abc.Sequence`, so we shortcut it here.
    if isinstance(value, list):
        return value

    if isinstance(value, (str, bytes, bytearray)):
        return None

    if isinstance(value, collections.abc.Sequence):
        return value

    return None


def is_safe_integer(
    value: int
) -> bool:
    """
    Check that :paramref:`value` lies in the safe integer range.

    The safe integer range [-2^53 + 1, 2^53 - 1] covers the integers which
    a double-precision floating-point number represents exactly. JSON knows
    a single numeric type, and the JSON de-serializers of the other languages
    read a number into such a float, so an integer outside of the range might
    quietly come out as a different number.

    Mind that a ``bool`` is an ``int`` in Python. The callers all sort out
    the booleans before they come here.

    :param value: integer to be checked
    :return: True if :paramref:`value` is a safe integer

    >>> is_safe_integer(2 ** 53 - 1)
    True

    >>> is_safe_integer(-(2 ** 53 - 1))
    True

    >>> is_safe_integer(2 ** 53)
    False

    >>> is_safe_integer(-(2 ** 53))
    False
    """
    return -9007199254740991 <= value <= 9007199254740991


def unsafe_integer_message(
    value: int
) -> str:
    """
    Describe that :paramref:`value` lies outside the safe integer range.

    See :py:func:`is_safe_integer`.
    """
    return (
        f"Expected an integer, but got {value}, "
        f"which is outside the safe integer range [-2^53 + 1, 2^53 - 1]"
    )


